if (e.code === 'EEXIST') {
        // Stale lock detection
        try {
          const stats = fs.statSync(LOCK_FILE);
          if (Date.now() - stats.mtimeMs > timeoutMs) {
            // Lock is older than timeout, assume it's stale
            console.warn(`[CITY-SPAWN] Found stale lock file (older than ${timeoutMs}ms). Removing...`);
            fs.unlinkSync(LOCK_FILE);
            continue; // Retry acquisition immediately
          }
        } catch (statErr) {}
        const end = Date.now() + 100;
        while (Date.now() < end) {}
      }

function releaseLock(fd) {
  try {
    if (fd !== undefined) {
      fs.fdatasyncSync(fd);
      fs.closeSync(fd);
    }
  } catch (e) {}
  try { fs.unlinkSync(LOCK_FILE); } catch(e) {}
}

